import 'package:rainbow_garden/handwriting.dart';

/// Independently authored, imperfect polylines, not samples of the production
/// Bezier paths. These exercise recognizable writing rather than exact tracing.
/// They are synthetic fixtures, not recordings from a child or a physical pen.
final Map<String, List<InkStroke>> writingSamples = {
  for (final e in _samples.entries)
    e.key: e.value
        .split('/')
        .map(
          (stroke) => stroke.trim().split(RegExp(r'\s+')).map((p) {
            final xy = p.split(',');
            return InkPoint(double.parse(xy[0]), double.parse(xy[1]));
          }).toList(),
        )
        .toList(),
};

